 function itemTile(id,detail=''){const i=itemById.get(id);if(!i)return '';const r=rarityById.get(i.rarity);return `<button class="loot-tile" data-item="${esc(id)}" style="--rare:${r.color}" title="${esc(i.name)} · ${esc(r.name)}"><span class="tile-image"><img src="${esc(i.icon)}" alt="" loading="lazy"></span><strong>${esc(i.name)}</strong>${rarityLabel(i)}${detail?`<small>${esc(detail)}</small>`:''}</button>`;}
 function setMode(mode,refresh=true){state.mode=mode;$('modeBuildings').setAttribute('aria-pressed',mode==='buildings');$('modePoints').setAttribute('aria-pressed',mode==='points');$('pointFilters').hidden=mode!=='points';$('placeHint').hidden=mode!=='buildings';$('visibleCount').textContent=mode==='buildings'?state.filteredBuildings.length:state.filtered.length;$('visibleUnit').textContent=mode==='buildings'?'локаций':'точек';if(refresh){closeDrawer();applyFilters();}else requestDraw();}
