  $('mapArea').querySelector('.map-heading .eyebrow').textContent=value==='hub'?'ХАБ / 02':'ГОРОД / 01';$('sidebar').querySelector('.section-title').firstChild.textContent=value==='hub'?'ХАБ ':'ЛУТИ-БЕЙ ';$('mapArea').setAttribute('aria-label',value==='hub'?'Интерактивный план хаба':'Интерактивная карта Лути-Бей');
  const m=value==='hub'?D.hub:cityMap;D.width=m.width;D.height=m.height;loaded=false;$('loading').hidden=false;state.fit=Math.min(state.w/D.width,state.h/D.height)*.95;home();image.src=value==='hub'?m.mapAsset:m.asset;
