 function buildingRow(b){return `<button class="point-row building-row" data-building="${esc(b.key)}"><img src="${esc(b.icon)}" alt=""><span class="row-text"><strong>${esc(b.name)}</strong><small>${esc(b.region)} · ${b.pointCount} точек</small></span><span class="row-arrow">↗</span></button>`;}
