 $('drawer').addEventListener('click',async e=>{const point=e.target.closest('[data-point]');if(point){openPoint(point.dataset.point,true);return;}const button=e.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;if(action==='close')closeDrawer();if(action==='found'&&state.selected){const id=state.selected;found.has(id)?found.delete(id):found.add(id);persist();categoryButtons();openPoint(id);applyFilters();}if(action==='share'){try{await navigator.clipboard.writeText(location.href);notify('Ссылка на точку скопирована');}catch{const line=document.createElement('p');line.className='list-hint';line.style.wordBreak='break-all';line.textContent=location.href;$('drawer').append(line);notify('Скопируй ссылку внизу карточки');}}});
