  const pts=e.target.closest('[data-building-points]'),cat=e.target.closest('[data-building-category]');if(pts||cat){const key=pts?.dataset.buildingPoints||state.selectedBuilding,building=buildingByKey.get(key);if(!building)return;state.query='';$('search').value='';state.region=building.region;$('region').value=state.region;state.building=building.name;buildingOptions();if(cat){state.cats=new Set([cat.dataset.buildingCategory]);categoryButtons();}setMode('points');fitPoints();showList(state.filtered,building.title,'Точки внутри выбранной локации.');setSidebar(false);}
