 const pointers=new Map();let drag=null,pinch=null;
 const xy=e=>{const r=canvas.getBoundingClientRect();return {x:e.clientX-r.left,y:e.clientY-r.top};};
 canvas.addEventListener('pointerdown',e=>{if(e.button&&e.button!==0)return;const p=xy(e);pointers.set(e.pointerId,p);canvas.setPointerCapture(e.pointerId);$('tooltip').hidden=true;if(pointers.size===1)drag={x:p.x,y:p.y,tx:state.tx,ty:state.ty,moved:false};else if(pointers.size===2){const [a,b]=[...pointers.values()];pinch={dist:Math.hypot(a.x-b.x,a.y-b.y)};if(drag)drag.moved=true;}canvas.classList.add('dragging');});
  canvas.addEventListener('pointermove',e=>{const p=xy(e);if(pointers.has(e.pointerId)){pointers.set(e.pointerId,p);if(pointers.size===2&&pinch){const [a,b]=[...pointers.values()],dist=Math.hypot(a.x-b.x,a.y-b.y);if(pinch.dist>0)zoomAt(dist/pinch.dist,(a.x+b.x)/2,(a.y+b.y)/2);pinch.dist=dist;}else if(drag){const dx=p.x-drag.x,dy=p.y-drag.y;if(Math.hypot(dx,dy)>4)drag.moved=true;state.tx=drag.tx+dx;state.ty=drag.ty+dy;requestDraw();}return;}const c=hit(p.x,p.y);canvas.style.cursor=c?'pointer':'grab';if(c&&e.pointerType!=='touch'){const t=$('tooltip');t.innerHTML=c.building?`${esc(c.building.name)}<small>${c.building.pointCount} точек лута · ${esc(c.building.region)}</small>`:c.shop?`${esc(c.shop.name)}<small>Обмен предметов</small>`:c.pts.length===1?`${esc(c.pts[0].name)}<small>${esc(c.pts[0].building||c.pts[0].region)} · нажми для деталей</small>`:`${c.pts.length} точек рядом<small>Нажми, чтобы раскрыть список</small>`;t.hidden=false;t.style.left=Math.max(8,Math.min(p.x+16,state.w-270))+'px';t.style.top=Math.max(8,Math.min(p.y+16,state.h-70))+'px';}else $('tooltip').hidden=true;});
 function release(e,cancel=false){const p=xy(e),wasPinch=!!pinch,wasMoved=drag?.moved;pointers.delete(e.pointerId);if(pointers.size===0){canvas.classList.remove('dragging');drag=null;pinch=null;if(!cancel&&!wasPinch&&!wasMoved){const c=hit(p.x,p.y);if(c)chooseCluster(c);else closeDrawer();}}else{pinch=null;const remaining=[...pointers.values()][0];drag={...remaining,tx:state.tx,ty:state.ty,moved:true};}}
 canvas.addEventListener('pointerup',e=>release(e));canvas.addEventListener('pointercancel',e=>release(e,true));canvas.addEventListener('pointerleave',()=>{$('tooltip').hidden=true;});
